. "$PSScriptRoot\Common-Utilities.ps1"
. "$PSScriptRoot\User-Safety.ps1"
function Get-OrganizationPlan { [CmdletBinding()]param([Parameter(Mandatory)][string]$Path);$root=Get-CanonicalPath $Path;$rules=Get-Content (Join-Path (Get-ToolkitPaths).Config 'Organization-Rules.json') -Raw|ConvertFrom-Json;Get-ChildItem -LiteralPath $root -File -Force|ForEach-Object {$cat='09_Needs_Review';foreach($r in $rules.psobject.Properties){if($_.Extension.ToLowerInvariant() -in @($r.Value)){$cat=$r.Name;break}};$dest=Join-Path (Join-Path $root $cat) $_.Name;[pscustomobject]@{Source=$_.FullName;Destination=$dest;Category=$cat;Risk=if(Test-SafeToMove $_ $dest){'YELLOW'}else{'UNKNOWN'};Action='Move after approval'}} }
function Invoke-FileOrganization {
 [CmdletBinding(SupportsShouldProcess=$true)]param([Parameter(Mandatory)][string]$Path,[switch]$Apply)
 $plan=@(Get-OrganizationPlan $Path);if(!$Apply){return $plan};$safe=@($plan|Where-Object {$_.Risk -eq 'YELLOW'});if(!(Confirm-ThreeTimes -Action 'Organizing files by category' -Summary "$($safe.Count) safe file(s) will be moved. Unsafe files will be skipped.")){return [pscustomobject]@{Mode='Cancelled';Moved=@();Plan=$plan}}
 $moved=[Collections.Generic.List[object]]::new();$skipped=[Collections.Generic.List[object]]::new();$i=0;foreach($item in $safe){$i++;Write-UserProgress 'Organizing folder' $i $safe.Count "Moving file $i of $($safe.Count)";try{New-Item -ItemType Directory -Path (Split-Path $item.Destination -Parent) -Force|Out-Null;Move-Item -LiteralPath $item.Source -Destination $item.Destination -ErrorAction Stop;$moved.Add($item)}catch{$skipped.Add([pscustomobject]@{Source=$item.Source;Reason=$_.Exception.Message})}};Write-Progress -Activity 'Organizing folder' -Completed;[pscustomobject]@{Mode='Complete';Moved=@($moved);Skipped=@($skipped);Message="$($moved.Count) file(s) organized."}
}